"""Prepare versioned, catalog-grounded family briefs; never overwrite a curated run."""
import json,re
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'docs/art/asset-concepts/2026-10-03'
OUT.mkdir(parents=True,exist_ok=True)
if (OUT/'prompts.json').exists(): raise SystemExit('Refusing to overwrite curated prompts')
STYLE='Use case: stylized-concept. Magenheim Valheim mod production reference sheet, landscape parchment-grey background, readable labeled studies, restrained Nordic handmade low-poly silhouettes with deliberately painted coarse texture detail. Main three-quarter view plus useful side/cutaway/material close-up. Honest irregular carving, worn contact surfaces and joinery; no smooth plastic, no sci-fi, no decorative random cubes or blobs. Detail must survive normal gameplay distance. Most microdetail belongs in albedo/normal/roughness textures, not extra geometry. Small neutral human scale silhouette where useful. Readable dark surfaces under neutral light, extremely limited luminous accents; no bloom or blown-out white highlights. This is concept art for later distillation, not a finished runtime mesh. '
rows=[]
def add(slug,name,category,biome,brief,members):
 rows.append(dict(id=slug,name=name,category=category,biome=biome,file=slug+'.png',members=members,prompt=STYLE+'Title: '+name+'. '+brief,status='planned'))
biomes=[
 ('fungal','Fungal Forest','Worldroot Timber; Glowcap Flesh; Spire Fibre; Understone','Worldroot Plank; Spire Cord; Cured Glowcap','Sporeweave','Worldroot Club; Worldroot Bow','Mycelial Bench','Sporelight Lantern','amber-brown fibrous root, moss-green waxy fungal tissue, pale woven fibres, grey porous Understone','Glowcap, Spirestalk, Puffcap, Tanglecap, ferns, sporebrush, rootgrass, moss-stone','integrated small root clamp and fibre-twisting spool; drying rack for sliced glowcap and a shallow working slab; joined wooden rails, accessible front working edge'),
 ('blackwater','Blackwater Deep','Blackwater Flowstone; Pale Fibre; Blackwater Pearl; Deep Salt','Flowstone Plate; Pale Cord; Brined Pearl','Palewater','Flowstone Maul; Blackwater Harpoon','Tidal Basin','Diving Bell Hood','blue-grey layered wet flowstone, pale braided fibres, creamy nacre and chalky salt crusts','Palefinger, pearl caps, brine fern, submerged roots, flowstone spires, rimstone mound, silt ripples','a real recessed basin set INTO the table: visible bowl depth and water, stone lip, drain channel and salt curing trays; cord reel attached to frame; section view proves inset construction'),
 ('sulfur','Sulfurous Wastes','Slagstone; Sulfur; Charred Timber; Emberiron','Emberiron Bar; Tempered Slag; Charred Root Grip','Emberiron','Emberiron Axe; Emberiron Greatsword','Furnace Heart Forge','Slag Pick','sooty charcoal grain, pitted dark slag, dull yellow sulfur crust, hammered black iron with scarce orange heat at working hearth','Cinderstalk with felled trunk and stump, split/rootbound/crown geothermal vents, sulfur drift banks','contained brick/slag hearth, bellows and tongs, Emberiron anvil and quencher; mechanically connected functional forge, heat-resistant compact legs; glow confined to hearth'),
 ('frozen','Frozen Caverns','Rimewood; Clear Ice; Rimesilver','Rimesilver Bar; Iceglass Lens; Rimewood Laminate','Rimeward','Rimesilver Spear; Icebind Staff','Silence Table','Rime Chisel','pale blue-grey laminated rootwood, frosted silver, clear ice with directional fractures; teal highlights and dull cloth','Rimecap, rime fans, frozen rootwood and ice/silver seam dressing','compact precision lapidary bench, hand-operated padded clamp and fine chisel guides, iceglass lens in a simple supported inspection stand; quiet table without giant ornaments'),
 ('fracture','Fracture Zones','Fracture Crystal; Shardstone; Titanbone','Titanbone Plate; Shardstone Block; Fracture Prism','Stoneanchor','Titanbone Atgeir; Shardstone Crossbow','Anchor Forge','Anchor Spike','heavy grey stratified shale, aged ivory bone, sparse violet mineral seams; cut prisms remain translucent without excessive glow','shale scree, exposed crystal seam, Titanbone deposit and fractured mineral outcrops','Titanbone-braced compact heavy forge; upper right hand crank firmly on an axle with bearings and offset hand grip, driving a visible press; small hexagonal sample crystals sit in a tray ON work surface, never in a leg'),
 ('decay','Great Decay','Rotwood; Decay Spore; Carrion Amber; Bone Gravel','Carrion Amber Seal; Ossuary Composite; Rotwood Laminate','Defiant','Amber Blade; Crown Sceptre','Crown Reliquary','Defiant Censer','dark red-brown rotten wood, aged yellow bone, translucent honey-red amber, black-green spore staining; dark yet readable','Rotbloom, peat mat, rotting roots, amber nodules and ossuary bone gravel','small functional sealing and composite pressing altar-workbench; amber heating cup, fitted bone moulds, press and curing tray; purposeful authority motifs integrated into frame, no unrelated furniture sculptures')]
for slug,biome,raw,refined,armour,weapons,station,tool,materials,flora,process in biomes:
 add(slug+'-materials',biome+' — gathered to worked materials','Materials',biome,'Catalog study board with each material clearly isolated and labeled. Raw pickups first row, refined products second row. Show recognizable transformation via matching grain/strata/fibre/nacre, not arbitrary identical colored crystals. Names: '+raw+'; '+refined+'. Material language: '+materials+'. Raw samples have natural fracture and asymmetry; refined forms show hand worked edges and use-specific stock shapes. Show ONLY the exact named raw and refined catalog members, with no additional foods or material entries. Glowcap Flesh where explicitly named is sliced mushroom tissue, not a rock.',(raw+'; '+refined).split('; '))
 add(slug+'-armour',armour+' armour set','Armour',biome,'Four-piece coordinated set: Helmet, Chest, Legs, Cape; full equipped front/side figure plus four separated material studies. Production constraint: helmet/chest/legs KEEP Valheim native Carapace donor segmented shell silhouette, joints and attachment structure. Design owned surface textures and palette over that donor, NOT a new freely sculpted suit. Cape retains native donor cloth silhouette and rig. '+materials+'. Materials from '+refined+'. Weather contact points and straps, modest distinguishing texture motifs. No floating spikes, opaque face replacement or impossible cloth. Cape donors by biome: Lox for Fungal, Linen for Blackwater, Ash for Sulfur, Wolf for Frozen, Asksvin for Fracture, TrollHide for Decay.',[armour+' '+s for s in ['Helmet','Chest','Legs','Cape']])
 add(slug+'-weapon-variants',weapons+' — Underworld derivatives','Weapon variants',biome,'Two clearly labeled derivative weapon design studies: '+weapons+'. Retain established crystal-grade weapon/staff ancestry, blade or head silhouette and functional grip. This sheet explores local material fittings, wraps and sockets rather than redesigning approved base weapons. '+materials+'. Upgrade materials: '+refined+'. Integrated collars follow the shaft/head junction; cords hold useful plates, no disconnected cubes. For Icebind Staff retain frost crystal staff identity. Show grip clearance with neutral hand study, fingers centered on handle not guard. Each weapon visible complete in side view; counterpart three-quarter material detail. Do not present these speculative proportions as approval to change base geometry.',weapons.split('; '))
 add(slug+'-station',station+' — working process','Stations',biome,'One compact bench with three-quarter, front working edge and meaningful cutaway of mechanism. '+process+'. '+materials+'. Scale similar to Valheim crafting station, roughly waist-high work surface, reachable from ground level; accessible front face, unobstructed feet and interaction. About 25% smaller than previous oversized mod tables. Worn corners, joinery and coarse handmade material grain; small asymmetry without random geometry. Clearly show raw inputs '+raw+' becoming '+refined+'. These are visual explanations of registered processes, not new gameplay systems.',[station])
 add(slug+'-tool',tool+' — functional construction','Tools',biome,'One tool reference sheet, complete side/three-quarter views and human handling study. '+materials+'. Constructed from '+refined+'. '+{'fungal':'Lantern MUST be carried by the TOP handle, with luminous fungus protected in a lower cage, never grasped below base; very restrained light.','blackwater':'Wearable diving hood with clear face aperture, closed neck seal and compact weighted rim; no modern scuba equipment; material coating must later fit retained native helmet donor.','sulfur':'Heavy purposeful pick with forge-mounted head, pointed mining end and charred bound grip, strong handle-head connection.','frozen':'Short precision ice-cutting chisel with a blunt striking butt and honed silver cutting edge, safe visibly usable handle.','fracture':'Deployable grounded spike, heavy bone collar and stone stabilizer foot around a single strong shaft; low center of gravity, grounded placement.','decay':'Hand-carried vented censer with secure upper handle, sealed amber chamber and bone grille; controlled dark vapour does not hide silhouette.'}[slug],[tool])
 add(slug+'-ecology',biome+' — vegetation and deposits','Ecology',biome,'Coherent environment asset kit board: '+flora+'. Include each named family at small/medium/large silhouette scale with one cut/felled state where applicable and matching raw resources '+raw+'. '+materials+'. Underground ecology; NO conventional surface trees. Mineral deposits are distinct harvestable seams/outcrops, especially Understone as grey stone rather than decorative mushrooms. Fungal canopy models must be tree-like in performance: sparse cap silhouette surfaces, gills mostly painted, no many radial fine-geometry layers. Ground scattering reusable cluster cards/simple mesh patches; avoid high-density individual blades. Visual design proposal only, not a generation performance measurement.',flora.split(', '))
add('fungal-foods','Fungal provisions — three actual recipes','Foods','Fungal Forest','Three separate clearly labeled plates and ingredient-to-food studies: Glowcap Stew (Glowcap Flesh, Royal Jelly, Sap), Mycelial Broth (Glowcap Flesh, Jotun Puffs, Sap), Heartcap Ration (Glowcap Flesh, Royal Jelly, Misthare Supreme). Stew is hearty cut fungal tissue in a worn wooden bowl; broth is thinner earthy stock with floating small fungi, ceramic cup/bowl; ration is dense prepared mushroom-heart and meat portion, leaf/fibre wrap. Appetite, readable texture, restrained tiny luminous flecks, no neon soup. All three identifiable at inventory icon size. Do not add unimplemented other-biome foods.',['Glowcap Stew','Mycelial Broth','Heartcap Ration'])
deep={'Annoyance Wisp':'tiny floating asymmetric mineral mote with a luminous recessed core and orbiting fragments, no humanoid legs','Geode Crawler':'low six-legged territorial crustacean with opened geode shell over back and jointed walking limbs','Shardling':'small agile biped with angled crystal plates, crouching skirmisher stance and distinct attack arm','Crystal Parasite':'compact eight-legged clinging arthropod with radial feeding mouth and crystalline parasite abdomen','Crystal Revenant':'skeletal humanoid soldier with mineral-replaced ribs and limbs, distinguish real joints and weapon arm','Facet Sentry':'compact upright construct with inset sensor aperture, articulated arms, planted stance and precision attack focus','Stone Sentinel':'tall broad gatekeeper with heavy interlocking stone plates, narrow head and firmly planted legs; distinguish from guardian','Crystal Hound':'lean four-legged pursuit predator, low long canine spine, articulated hind hocks and mineral jaw; crystal fur silhouette restrained','Burrower':'horizontal segmented subterranean worm-beast with wedge digging mouth, fore digging limbs and trailing tapered body; show excavation pose','Stone Guardian':'low wide quadrupedal gatekeeper, buttressed stone limbs, shield-like front head, weight-bearing stone anatomy','Crystal Golem':'massive articulated biped with coherent geode torso, overlapping shoulder plates and weighty mineral hands, not random shard stack','Obelisk Warden':'stationary living upright obelisk fortification with integrated rooted base, inset core and stone rib shutters; no walking humanoid copy','Deep Colossus':'huge hunched stratified cavern titan, very long load-bearing arms, thick short legs, torso vault and giant split mineral face; clearly different from Crystal Golem'}
for name,anatomy in deep.items():
 slug=re.sub('[^a-z0-9]+','-',name.lower())
 add('deep-'+slug,name+' — Deep Fracture chassis','Creatures','Deep Fractures','Dedicated creature design target: '+anatomy+'. Hero three-quarter neutral pose, side silhouette, scale figure and anatomy/material callouts. Continuous connected anatomy, attack organ and joint motion clear. Coarse chipped layered stone, rough crystal, dark recessed seams. One neutral earth mineral body and small palette strip for earth/fire/frost/storm/venom/radiance/spirit/seidr alignment. Alignments change material accents, not chassis identity. Retain donor-compatible rig and behavior; resolve generated view inconsistencies before modeling. Different from the Underworld biome creature names already adopted.',[name])
add('elemental-surtlings','Elemental Surtlings — six paired identities','Creatures','Underworld elemental','Family design board of six masculine/feminine pairs, 12 compact elemental humanoids labeled Earth, Fire, Wind, Water, Radiance, Umbral. Shared humanoid bone-role contract, six distinct elemental physiques: Earth male enormous barrel-chested thick-waisted strongman and female heavily powerful; Fire athletic; Water swimmer; Wind very lean runner/dancer; Radiance classical; Umbral elongated and predatory. Each element has its own masculine/feminine build, no sexualization. Earth cracked stone/root seams, Fire charred crust/contained ember, Wind eroded aerated bands, Water flowing dark mineral/nacre, Radiance pale chalk/gold recessed core, Umbral dark rock/red recessed eyes. Distinct elemental mass, proportions and material flow, recognizable as one spirit family. No superhero armour, no copied giant elemental silhouettes.',['Earth Surtling','Fire Surtling','Wind Surtling','Water Surtling','Radiance Surtling','Umbral Surtling'])
add('rootforged-modular-kit','Rootforged — joined building kit','Architecture','Shared','Construction board showing Worldroot 2/4/8m beams and pillars, forked columns, T/Y braces, 4m floor, 4/8m arch ribs, Understone 2x2 foundation, stairs, iron-banded beams and column plinth. Not architectural rendering alone: orthographic endpoint studies and a small assembled bay. Even arch feet both meet grid, symmetric endpoints align 1m/2m attachment grid. Floor underside logs extend to meet adjacent tile logs. All structural members remain substantial entwined roots, braided and knotty through beams, columns, braces, arches and floor supports. Natural root curves meet deliberately grid-aligned endpoints. Never ordinary sawn timber. Bark grain keeps consistent physical scale; bands genuinely bind root bundles. Real modular joinery, no checkerboard textures.', ['Worldroot building family','Rootforged arches','Understone foundation/stairs'])
add('crystal-building-kit','Crystal structures — load paths and joints','Architecture','Shared','Modular crystal structural family: 2/4/8m beams and foundations, pillars/hearth/wardstone/light fittings. Faceted structural mineral with dark iron or stone connection shoes, believable continuous load paths and visibly meeting endpoints. Show vertical, horizontal and perpendicular connection examples with modest joinery overlap. Architecture stays modular and Valheim human-scaled, not giant glowing polygon slab. Geometric contact drawing is a visual intention, not evidence that runtime stability works. Include pennant, standard, swallowtail motifs as texture designs, not geometry-heavy banners.', ['Crystal architecture','Crystal wardstone','Crystal lighting','Crystal banners'])
add('blackstone-architecture','Blackstone — civic and throne architecture','Architecture','Shared','Unified kit: cathedral wall and buttress, floor tile, pillar, arch, stair, terrace, parapet, bridge, cliff edge, spire, gate, dais, throne, attendant seat, banner and brazier. Worn dark layered stone with sparse restrained crystal inlays; believable masonry and edges, human door scale, disciplined Nordic underground regal motifs. Show modular bay and small isolated kit pieces. No vast monumental overscaling of usable furniture.', ['Blackstone architecture family','Dark throne'])
add('mineral-furniture','Mineral furnishings — lived-in craftsmanship','Furniture','Shared','Coherent domestic furnishings board: crystal bed, bench, divider, throne; geode chair/table/pedestal; geo desk, lapidary cabinet, mineral shelf; coat rack, end table, wall sconce, geode bowl, hearth mantel, geologist stool, specimen sideboard, mineral display case, strata map table, cut geode plaque. Wood/stone joinery supports mineral inserts. Draw fitted drawers with inset fronts, seams and pulls, not cubes with handles. Worn surfaces and useful storage, consistent scale. Clearly restrained coarse game texture detail.', ['Crystal furniture family','Geological decor family'])
add('fracture-dungeon-kit','Deep Fractures — enclosed dungeon language','Architecture','Deep Fractures','Underground dungeon visual kit for descent, passage, traversal and 20 chamber families. Core wall/ceiling/floor/doorway vocabulary plus environment variants thermal, rime, conduction, compression, contamination, prism, echo, ossuary and shaping. Sealed roof and controlled recessed illumination. Surface access uses a reused Valheim cave entrance, not homemade exposed corridor piles. Section study shows chambers safely isolated below terrain with roof, no daylight aperture. Deep Gate references the native AESIR GATE shape: tall portal frame with bound stone/wood uprights; never Forge of Potential crafting bench. Exact native gate identity remains authoritative over this illustrative study.', ['DF-01 through DF-20','Deep Fracture entrance/passage/traversal','Deep Gate'])
add('arcane-materials-workshop','Crystal progression — materials and working tools','Items','Shared','Design board of geode, rough crystal, shards, simple/advanced/master/crystal grades, elemental focus, fate shard/crystal, geode sample; eight boss heart variants rooted in native boss identities; faceting wheel, fracturing block, resonance frame, crystal enchanting dais, rune engraver, norn spindle, runed totem, runic keelstone, passage stone, seidr ritual focus and raven/wolf/warrior spirit fetishes. Material progression: rough natural fracture -> sorted splinters -> purposeful worked facets -> fitted small rune components, never simply bigger luminous rocks. Native boss icon cues, spare Nordic texture-carved motifs. Tool processes visibly connected. Small readable silhouette studies grouped raw/worked/tools/rituals. Preserve approved staff and crystal weapon identities entirely.', ['Crystal resource progression','Boss hearts','Arcane working and ritual props'])
add('null-mantle-regalia','Null Mantle and Underworld regalia','Special equipment','Great Decay','Null Mantle: native cape silhouette retained, owned charcoal-black coarse cloth with dark amber-red hem seals and narrow bone fastenings, wear at hem and shoulder. Front/rear equipped reference plus head close-up; paired red eyes sit ON the eye sockets with sharply bounded dim glow, never behind the head. Strong local wearer darkening while equipped but body silhouette remains readable; annotation effect applies only when equipped. Broken Crown and dark throne motifs harmonize authority without imitating the surface crown. Preserve existing Firmament/Null Gate sword base geometry; show small MATERIAL swatches only for their fittings, do not invent new full swords. Design of presentation does not change gameplay royalty rules.', ['Null Mantle','Broken Crown','Underworld regalia materials'])
(OUT/'prompts.json').write_text(json.dumps(rows,indent=2),encoding='utf-8')
print('Prepared',len(rows),'named reference sheets in',OUT)
